import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;import java.io.PrintWriter;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);StringTokenizer st = new StringTokenizer(br.readLine());int t = Integer.parseInt(st.nextToken());while (t-- > 0) {int n = Integer.parseInt(br.readLine().trim());String s = br.readLine().trim();int count0 = 0;int count1 = 0;for (int i = 0; i < n; i++) {if (s.charAt(i) == '0') {count0++;} else {count1++;}}int moves = Math.min(count0, count1);if (moves % 2 != 0) {out.println("Zlatan");} else {out.println("Ramos");}}out.flush();out.close();}}